// these functions are imported into code generated by protoc-gen-native
// DO NOT make this a dependency of anything
// as of now, only this file is parsed, not even the entire package.

// when adding a proto Converter, you must add it in both directions:

// ToNative Converter naming format:
//		ConvertProtoTo<baseTypeName>[Pointer][Slice]
//
// function signature:
//		func(protoType) (nativeType, error)

// ToProto Converter naming format:
//		Convert<baseTypeName>[Pointer][Slice]ToProto
//
// function signature:
//		func(nativeType) (protoType, error)

// To disable redundant gopls ide errors in vsc, add this to .vscode/settings.json:
// "gopls": { "ui.diagnostic.analyses": { "unusedfunc": false } }

func ConvertDurationToProto(d time.Duration) (*durationpb.Duration, error) {
	return durationpb.New(d), nil
}

func ConvertProtoToDuration(d *durationpb.Duration) (time.Duration, error) {
	if d == nil {
		return 0, nil
	}
	return d.AsDuration(), nil
}

func ConvertTimeToProto(t time.Time) (*timestamppb.Timestamp, error) {
	return timestamppb.New(t), nil
}

func ConvertProtoToTime(t *timestamppb.Timestamp) (time.Time, error) {
	if t == nil {
		return time.Time{}, nil
	}
	return t.AsTime(), nil
}

func ConvertTimePointerToProto(t *time.Time) (*timestamppb.Timestamp, error) {
	if t == nil {
		return nil, nil
	}
	return ConvertTimeToProto(*t)
}

func ConvertProtoToTimePointer(t *timestamppb.Timestamp) (*time.Time, error) {
	if t == nil {
		return nil, nil
	}
	timePtr, err := ConvertProtoToTime(t)
	return &timePtr, err
}

func ConvertUUIDToProto(id uuid.UUID) (string, error) {
	if id == uuid.Nil {
		return "", nil
	}
	return id.String(), nil
}

func ConvertProtoToUUID(id string) (uuid.UUID, error) {
	if len(id) == 0 {
		return uuid.Nil, nil
	}
	return uuid.Parse(id)
}

func ConvertNullUUIDToProto(id uuid.NullUUID) (*string, error) {
	if !id.Valid {
		return nil, nil
	}
	uuidVal, err := ConvertUUIDToProto(id.UUID)
	if err != nil {
		return nil, err
	}
	return &uuidVal, nil
}

func ConvertProtoToNullUUID(id *string) (uuid.NullUUID, error) {
	if id == nil {
		return uuid.NullUUID{}, nil
	}
	parsed, err := ConvertProtoToUUID(*id)
	if err != nil {
		return uuid.NullUUID{}, err
	}
	return uuid.NullUUID{
		UUID:  parsed,
		Valid: true,
	}, nil
}

func ConvertUUIDSliceToProto(ids []uuid.UUID) ([]string, error) {
	result := make([]string, len(ids))
	for i, id := range ids {
		encoded, err := ConvertUUIDToProto(id)
		if err != nil {
			return nil, err
		}
		result[i] = encoded
	}
	return result, nil
}

func ConvertProtoToUUIDSlice(ids []string) ([]uuid.UUID, error) {
	result := make([]uuid.UUID, len(ids))
	for i, id := range ids {
		parsed, err := ConvertProtoToUUID(id)
		if err != nil {
			return nil, err
		}
		result[i] = parsed
	}
	return result, nil
}

func ConvertKeyUsageToProto(ku x509.KeyUsage) ([]x509pb.KeyUsage, error) {
	var result []x509pb.KeyUsage

	if ku&x509.KeyUsageDigitalSignature != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_DIGITAL_SIGNATURE)
	}
	if ku&x509.KeyUsageContentCommitment != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_CONTENT_COMMITMENT)
	}
	if ku&x509.KeyUsageKeyEncipherment != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_KEY_ENCIPHERMENT)
	}
	if ku&x509.KeyUsageDataEncipherment != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_DATA_ENCIPHERMENT)
	}
	if ku&x509.KeyUsageKeyAgreement != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_KEY_AGREEMENT)
	}
	if ku&x509.KeyUsageCertSign != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_CERT_SIGN)
	}
	if ku&x509.KeyUsageCRLSign != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_CRL_SIGN)
	}
	if ku&x509.KeyUsageEncipherOnly != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_ENCIPHER_ONLY)
	}
	if ku&x509.KeyUsageDecipherOnly != 0 {
		result = append(result, x509pb.KeyUsage_KEY_USAGE_DECIPHER_ONLY)
	}

	return result, nil
}

func ConvertProtoToKeyUsage(keyUsages []x509pb.KeyUsage) (x509.KeyUsage, error) {
	var result x509.KeyUsage

	for _, ku := range keyUsages {
		switch ku {
		case x509pb.KeyUsage_KEY_USAGE_DIGITAL_SIGNATURE:
			result |= x509.KeyUsageDigitalSignature
		case x509pb.KeyUsage_KEY_USAGE_CONTENT_COMMITMENT:
			result |= x509.KeyUsageContentCommitment
		case x509pb.KeyUsage_KEY_USAGE_KEY_ENCIPHERMENT:
			result |= x509.KeyUsageKeyEncipherment
		case x509pb.KeyUsage_KEY_USAGE_DATA_ENCIPHERMENT:
			result |= x509.KeyUsageDataEncipherment
		case x509pb.KeyUsage_KEY_USAGE_KEY_AGREEMENT:
			result |= x509.KeyUsageKeyAgreement
		case x509pb.KeyUsage_KEY_USAGE_CERT_SIGN:
			result |= x509.KeyUsageCertSign
		case x509pb.KeyUsage_KEY_USAGE_CRL_SIGN:
			result |= x509.KeyUsageCRLSign
		case x509pb.KeyUsage_KEY_USAGE_ENCIPHER_ONLY:
			result |= x509.KeyUsageEncipherOnly
		case x509pb.KeyUsage_KEY_USAGE_DECIPHER_ONLY:
			result |= x509.KeyUsageDecipherOnly
		case x509pb.KeyUsage_KEY_USAGE_UNSPECIFIED:
			// skip unspecified
		default:
			// skip unknown values
		}
	}

	return result, nil
}

