func ConvertObjectIdentifierToProto(oid asn1.ObjectIdentifier) (string, error) {
	return oid.String(), nil
}

func ConvertProtoToObjectIdentifier(oidStr string) (asn1.ObjectIdentifier, error) {
	parts := strings.Split(oidStr, ".")
	if len(parts) < 2 {
		return nil, fmt.Errorf("invalid OID format '%s': must have at least two components", oidStr)
	}

	// Create the OID slice
	oid := make(asn1.ObjectIdentifier, len(parts))

	// Convert each component to an integer
	for i, part := range parts {
		val, err := strconv.Atoi(part)
		if err != nil {
			return nil, fmt.Errorf("invalid OID component '%s': %w", part, err)
		}
		if val < 0 {
			return nil, fmt.Errorf("invalid OID component '%d': cannot be negative", val)
		}

		// Basic validation on components
		if i == 0 && val > 2 {
			return nil, fmt.Errorf("invalid first OID component '%d': must be 0, 1, or 2", val)
		}
		if i == 1 && val > 39 && oid[0] < 2 {
			return nil, fmt.Errorf("invalid second OID component '%d': when first component is %d, second component must be <= 39", val, oid[0])
		}

		oid[i] = val
	}

	return oid, nil
}

func ConvertObjectIdentifierSliceToProto(oidSlice []asn1.ObjectIdentifier) ([]string, error) {
	var oidStrs []string
	for _, oid := range oidSlice {
		oidStr, err := ConvertObjectIdentifierToProto(oid)
		if err != nil {
			return nil, fmt.Errorf("failed to Convert OID to proto: %w", err)
		}
		oidStrs = append(oidStrs, oidStr)
	}
	return oidStrs, nil
}

func ConvertProtoToObjectIdentifierSlice(oidStrSlice []string) ([]asn1.ObjectIdentifier, error) {
	var oids []asn1.ObjectIdentifier
	for _, oidStr := range oidStrSlice {
		oid, err := ConvertProtoToObjectIdentifier(oidStr)
		if err != nil {
			return nil, fmt.Errorf("failed to Convert OID to proto: %w", err)
		}
		oids = append(oids, oid)
	}
	return oids, nil
}

