func ConvertProtoToExtension(extension *x509pb.Extension) (pkix.Extension, error) {
	oid, err := StringToOID(extension.Id)
	if err != nil {
		return pkix.Extension{}, fmt.Errorf("failed to convert extension ID to OID: %w", err)
	}
	return pkix.Extension{
		Id:       oid,
		Critical: extension.Critical,
		Value:    extension.Value,
	}, nil
}

